    private static uint Hash(string text){uint h=2166136261;foreach(char c in text)h=unchecked((h^c)*16777619);return h;}
    private static IEnumerable<string> Adults(JsonObject family){var members=A(family["members"]);var names=A(family["names"]);for(int i=0;i<members.Count;i++){var match=Regex.Match(S(names.ElementAtOrDefault(i)),@"\((\d+)\)");if(match.Success&&int.Parse(match.Groups[1].Value)>=13)yield return S(members[i]);}}
    public JsonObject Tick(bool quiet=false)
    {
        var state=State;var result=new JsonObject{["changed"]=false,["arrived"]=new JsonArray(),["boarded"]=new JsonArray(),["scam"]=null};if(state==null)return result;bool townChanged=false,changed=false;var families=A(state["families"]);
        for(int n=0;n<200;n++){double arrival=ArrivalOf(n);if(arrival>Now&&!DevEarly.Contains(n))break;if(families.Any(f=>N(f,"n")==n))continue;int board=BoardDayOf(arrival);if(Day>board||Day==board&&Hour>=19){var made=MakeFamily((uint)N(state,"seed"),n,0,FamilyHome(state),families.Select(f=>S(f,"surname")));var family=made["family"]!.DeepClone().AsObject();family["slot"]=0;family["props"]=made["props"]!.DeepClone();family["status"]="boarded";family["boarded"]=new JsonObject{["day"]=board,["hour"]=19,["by"]="engine"};family["done"]=new JsonArray();families.Add(family);continue;}families.Add(Arrive(state,n,quiet));A(result["arrived"]).Add(n);townChanged=true;}
        foreach(var family in families.OfType<JsonObject>()){if(S(family,"status")!="here")continue;if(Day>N(family,"board_day")||Day==N(family,"board_day")&&Hour>=19){Board(state,family,"engine");A(result["boarded"]).Add((int)N(family,"n"));townChanged=true;}}
        if(!quiet){if(IsShipDay(Day)&&Hour>=6&&!A(state["notices"]).Any(d=>V(d)==Day)){A(state["notices"]).Add(Day);C.Execute("INSERT INTO world_fact(text,weight,day,tags) VALUES($p0,5,$p1,'notice,emigrants')","Red Star Line: the KEMPENLAND at anchor off the Rijnkaai takes her emigrants on board today. Lighters from the quay from seven in the morning.",Day);changed=true;}string? scam=RunnerTick(state);result["scam"]=scam;if(scam!=null)changed=true;if(ErrandsTick(state))changed=true;}
        C.SetWorld("emigrants",state);if(townChanged)Invalidate?.Invoke();result["changed"]=changed||townChanged;return result;
    }
    private string? RunnerTick(JsonObject state)
    {
        var scam=state["scam"]as JsonObject;if(scam!=null&&S(scam,"state")=="working"&&Now>=N(scam,"until")){scam["state"]="sold";var family=A(state["families"]).OfType<JsonObject>().FirstOrDefault(f=>N(f,"n")==N(scam,"family"));if(family!=null&&S(family,"status")=="here"){family["scammed"]=true;family["lost_c"]=1500+(int)(C.Roll()*16)*100;foreach(string id in Adults(family))host.Trade.Remember(1,id,"A kind man on the quay sold us railway tickets for the journey on from Philadelphia, "+(int)Round(N(family,"lost_c")/100)+" francs. The keeper says they are worthless paper.",6);host.Trade.Remember(1,S(state,"runner"),"I sold the "+S(family,"surname")+" family a fine set of railway tickets. Good day's work.",4);C.Log(1,"runner_sold",((int)N(family,"household")).ToString(),"A runner on the Rijnkaai sold the "+S(family,"surname")+" family false railway tickets for "+(int)Round(N(family,"lost_c")/100)+" francs.");}return "sold";}
        if(scam!=null&&N(scam,"day")==Day||B(state,"runner_jailed")||A(state["scam_days"]).Any(d=>V(d)==Day))return null;double at=10+Hash(((uint)N(state,"seed"))+":"+Day)%100/100.0*1.5;if(Hour<at||Hour>=15)return null;A(state["scam_days"]).Add(Day);if(C.Roll()>=.7)return null;var target=A(state["families"]).OfType<JsonObject>().Where(f=>S(f,"status")=="here"&&N(f,"board_day")!=Day&&!B(f,"scammed")&&!B(f,"warned")&&Now-N(f,"arrive")>=2&&Adults(f).Any()).OrderByDescending(f=>N(f,"arrive")).FirstOrDefault();if(target==null)return null;state["scam"]=new JsonObject{["day"]=Day,["family"]=target["n"]!.DeepClone(),["start"]=Now,["until"]=Math.Min(Now+4,(Day-1)*24+15.5),["state"]="working"};C.Log(1,"runner_working",((int)N(target,"household")).ToString(),"A smooth-talking man was seen with the "+S(target,"surname")+" family on the Rijnkaai, showing them papers.");return "working";
    }
    public JsonObject WarnFamily(int player,string by)
    {
        var state=State;var scam=state?["scam"]as JsonObject;var family=scam==null?null:A(state?["families"]).OfType<JsonObject>().FirstOrDefault(f=>N(f,"n")==N(scam,"family"));if(state==null||scam==null||family==null||S(scam,"state")!="working"||S(family,"status")!="here"||!A(family["members"]).Any(m=>S(m)==by))return new(){["ok"]=false,["text"]="",["trust"]=0};scam["state"]="warned";scam["by"]=by;family["warned"]=true;foreach(string id in Adults(family)){if(id==by)continue;host.Rumours.ApplyTrust(id,player,1,0);host.Trade.Remember(player,id,"Jef, a young man of the quay, warned us that the man's tickets were false. He saved our money.",6);}host.Trade.Remember(player,by,"Jef warned me the smooth man's railway tickets were false. He saved our money.",7,"Jef warned the emigrants off a runner's false tickets",2);host.Trade.Remember(player,S(state,"runner"),"That lad Jef spoiled my sale to the emigrants on the quay.",5,"Jef sticks his nose in other men's business on the Rijnkaai",-1);C.Log(player,"warned_emigrants",((int)N(family,"household")).ToString(),"Jef warned the "+S(family,"surname")+" family that the runner's tickets were false.");ErrandsTick(state);C.SetWorld("emigrants",state);var errand=OpenErrand(state,family);var head=by==S(family,"head")?null:actions.Resident(S(family,"head"));string ask=errand!=null&&S(errand,"kind")=="watch"&&S(errand,"status")=="offered"?" Please, will you watch our things while we go to the office to ask about the tickets? "+(int)N(errand,"pay_c")+" centimes, we pay."+(head==null?"":" "+S(head,"first")+" will tell you."):"";return new(){["ok"]=true,["text"]=ask,["trust"]=2};
    }
    public JsonObject ReportRunner(int player,string agent)
    {
        var state=State;var scam=state?["scam"]as JsonObject;if(state==null||scam==null||B(state,"runner_jailed")||N(scam,"day")!=Day||S(scam,"state")is not("working"or"sold"))return new(){["ok"]=false,["returned"]=false};var family=A(state["families"]).OfType<JsonObject>().FirstOrDefault(f=>N(f,"n")==N(scam,"family"));bool returned=S(scam,"state")=="sold"&&family!=null&&S(family,"status")=="here";scam["state"]="reported";scam["by"]=agent;state["runner_jailed"]=true;C.Execute("UPDATE faction_trust SET trust=MAX(-5,MIN(10,trust+1)) WHERE faction='politie' AND player_id=$p0",player);host.Trade.Remember(player,agent,"Jef told me a runner was selling false tickets to the emigrants on the Rijnkaai. We took the man in.",6,"Jef reported the ticket runner on the Rijnkaai to the police",1);host.Trade.Remember(player,S(state,"runner"),"The police took me in off the Rijnkaai. Somebody talked: that lad Jef.",7,"Jef went to the police about honest men's business on the quay",-2);if(family!=null&&S(family,"status")=="here"){if(returned)family["returned"]=true;foreach(string id in Adults(family))host.Trade.Remember(player,id,returned?"The police made the smooth man give back our money. Jef went to them for us.":"The police took away the man with the papers. Jef went to them.",6);}var runner=actions.Resident(S(state,"runner"));if(runner!=null){var police=Facts["policePost"]!;runner["home"]=new JsonObject{["house"]=-1,["x"]=police["door"]![0]!.DeepClone(),["z"]=police["door"]![1]!.DeepClone(),["sx"]=police["x"]!.DeepClone(),["sz"]=police["z"]!.DeepClone()};runner["sched"]=new JsonObject{["day"]=new JsonArray(),["sunday"]=new JsonArray()};Insert(runner);Invalidate?.Invoke();}C.Log(player,"reported_runner",S(state,"runner"),"Jef reported the runner who sold false tickets to the emigrants; the police took him in"+(returned?" and made him give the money back":"")+".");C.SetWorld("emigrants",state);return new(){["ok"]=true,["returned"]=returned};
    }
    private static string? Wanted(JsonObject f,int day,double hour){foreach(string kind in new[]{"luggage","watch","lost_chest"}){if(A(f["done"]).Any(d=>S(d)==kind))continue;if(kind=="luggage"&&N(f,"board_day")==day&&hour>=6)return kind;if(kind=="watch"&&B(f,"warned")&&N(f,"board_day")!=day)return kind;if(kind=="lost_chest"&&f["lost_chest"]!=null&&N(f,"board_day")!=day)return kind;}return null;}
    public static JsonObject ErrandJob(JsonObject family,string kind)
    {
        string surname=S(family,"surname");if(kind=="luggage"){int n=Math.Min((int)N(family,"chests"),2);return new(){["title"]="The "+surname+" family's "+(n==1?"chest":"chests")+" to the lighter",["type"]="carry",["pay"]=10+15*n,["pitch"]=(n==1?"Our chest":"Our two big chests")+", from our place on the quay across the rails to the lighter berth"+(N(family,"chests")>n?"; we carry the small one ourselves":"")+". The lighter takes us out to the ship today.",["task"]=new JsonObject{["kind"]="carry",["goods"]="chests",["count"]=n,["from"]="emigrant_quay",["to"]="lighter_berth",["twist"]="none",["limit_s"]=null}};}if(kind=="watch")return new(){["title"]="Watch the "+surname+" family's things",["type"]="watch",["pay"]=45,["pitch"]="Please watch our chests while we go to the agent's office to see our tickets are good. There are thieves about.",["task"]=new JsonObject{["kind"]="watch",["goods"]="chests",["post"]="emigrant_quay",["duration_s"]=90,["twist"]="thief"}};return new(){["title"]="Find the "+surname+" family's lost chest",["type"]="carry",["pay"]=60,["pitch"]="Our small chest never came to the quay. The carter says he put it down "+S(family["lost_chest"],"where")+". Please bring it to our place on the quay.",["task"]=new JsonObject{["kind"]="carry",["goods"]="chests",["count"]=1,["from"]=S(family["lost_chest"],"spot"),["to"]="emigrant_quay",["twist"]="none",["limit_s"]=null}};
    }
    private bool ErrandsTick(JsonObject state)
    {
        bool changed=false;string Status(int id)=>C.Scalar<string>("SELECT status FROM job WHERE id=$p0",id)??"expired";foreach(var er in A(state["errands"])){var family=A(state["families"]).FirstOrDefault(f=>N(f,"n")==N(er,"family"));string status=Status((int)N(er,"job"));if(family!=null&&status is "done"or"failed"&&!A(family["done"]).Any(d=>S(d)==S(er,"kind")))A(family["done"]).Add(S(er,"kind"));}
        foreach(var family in A(state["families"]).OfType<JsonObject>()){if(S(family,"status")!="here")continue;string? want=Wanted(family,Day,Hour);var live=A(state["errands"]).Where(er=>N(er,"family")==N(family,"n")&&N(er,"day")==Day&&Status((int)N(er,"job"))is "offered"or"taken").ToArray();foreach(var er in live)if(S(er,"kind")!=want&&Status((int)N(er,"job"))=="offered"){C.Execute("UPDATE job SET status='expired' WHERE id=$p0",(int)N(er,"job"));changed=true;}if(want==null||live.Any(er=>S(er,"kind")==want)||live.Any(er=>Status((int)N(er,"job"))=="taken"))continue;var job=ErrandJob(family,want);C.Execute("INSERT INTO job(day,title,employer_npc,district,task_type,pay_c,risk,tier,required_faction,pitch,task_json,source,status) VALUES($p0,$p1,$p2,'rijnkaai',$p3,$p4,'low',0,NULL,$p5,$p6,'emigrant','offered')",Day,S(job,"title"),S(family,"head"),S(job,"type"),(int)N(job,"pay"),S(job,"pitch"),job["task"]!.ToJsonString());int id=C.Scalar<int>("SELECT last_insert_rowid()");A(state["errands"]).Add(new JsonObject{["family"]=family["n"]!.DeepClone(),["kind"]=want,["job"]=id,["day"]=Day});changed=true;}return changed;
    }
    private JsonObject? OpenErrand(JsonObject state,JsonObject family){foreach(var er in A(state["errands"]).Where(er=>N(er,"family")==N(family,"n")&&N(er,"day")==Day)){var job=C.One("SELECT title,pay_c,status,pitch FROM job WHERE day=$p0 AND id=$p1 AND status IN('offered','taken')",Day,(int)N(er,"job"));if(job!=null){job["kind"]=S(er,"kind");return job;}}return null;}
    private JsonObject Dev(NativeServiceRequest request)
    {
        var state=State;if(state==null)return new(){["ok"]=false,["why"]="no emigrants"};var notes=new JsonArray();if(request.Bool("ship_today")){foreach(var f in A(state["families"]).Where(f=>S(f,"status")=="here"))f!["board_day"]=Day;notes.Add("the waiting families go out today");}if(request.Bool("runner")){var family=A(state["families"]).Where(f=>S(f,"status")=="here"&&N(f,"board_day")!=Day).OrderByDescending(f=>N(f,"arrive")).FirstOrDefault();if(family!=null){state["scam"]=new JsonObject{["day"]=Day,["family"]=family["n"]!.DeepClone(),["start"]=Now,["until"]=Now+4,["state"]="working"};state["runner_jailed"]=false;notes.Add("the runner works the "+S(family,"surname")+" family");}}C.SetWorld("emigrants",state);if(request.Bool("arrive")){int next=A(state["families"]).Count;notes.Add("family "+next+" arrives");DevEarly.Add(next);}if(request.Body["board"]is JsonValue value&&value.TryGetValue<int>(out int household))notes.Add(BoardByLighter(household,true).ToJsonString());Tick();host.Publish("emigrants",new JsonObject());host.Publish("jobs",host.Payload(request.PlayerId));return new(){["ok"]=true,["notes"]=notes,["view"]=View()};
    }
}
